<?php
require_once __DIR__.'/config/db.php'; require_once __DIR__.'/includes/functions.php';
garantir_schema_expandido($pdo); exigir_login(); processar_acao_favorito($pdo);
$usuarioId=(int)(usuario_logado()['id']??0); $flash=''; $tipoFlash='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!verificar_csrf()) throw new RuntimeException('Sessão expirada. Atualize a página.');
  $tipo=$_POST['tipo']??''; $id=(int)($_POST['item_id']??0);
  $map=['time'=>['times','id'],'jogador'=>['jogadores','id'],'confronto'=>['confrontos','id']];
  if(!isset($map[$tipo])||$id<1) throw new RuntimeException('Selecione um item válido.');
  [$tabela,$coluna]=$map[$tipo]; $q=$pdo->prepare("SELECT COUNT(*) FROM `$tabela` WHERE `$coluna`=?");$q->execute([$id]);
  if(!(int)$q->fetchColumn()) throw new RuntimeException('Esse item não existe mais.');
  if(($_POST['acao']??'')==='remover'){$q=$pdo->prepare('DELETE FROM favoritos WHERE usuario_id=? AND tipo=? AND item_id=?');$q->execute([$usuarioId,$tipo,$id]);$flash='Favorito removido.';}
  else{$q=$pdo->prepare('INSERT IGNORE INTO favoritos(usuario_id,tipo,item_id) VALUES(?,?,?)');$q->execute([$usuarioId,$tipo,$id]);$flash='Adicionado aos favoritos.';}
 }catch(Throwable $e){$flash=$e instanceof RuntimeException?$e->getMessage():'Não foi possível atualizar os favoritos.';$tipoFlash='error';}
}
$times=$pdo->query('SELECT id,nome FROM times ORDER BY nome')->fetchAll();
$players=$pdo->query('SELECT j.id,j.nome,j.numero,t.nome time_nome FROM jogadores j JOIN times t ON t.id=j.time_id ORDER BY t.nome,j.numero')->fetchAll();
$matches=$pdo->query('SELECT c.id,c.data_hora,c.quadra,c.cidade,c.estado,a.nome casa,b.nome fora,c.gols_casa,c.gols_visitante FROM confrontos c JOIN times a ON a.id=c.time_casa JOIN times b ON b.id=c.time_visitante ORDER BY c.data_hora,c.id')->fetchAll();
$q=$pdo->prepare("SELECT f.tipo,f.item_id, f.criado_em, t.nome time_nome,j.nome jogador_nome,j.numero, a.nome casa,b.nome fora,c.data_hora,c.gols_casa,c.gols_visitante,c.quadra,c.cidade,c.estado FROM favoritos f LEFT JOIN times t ON f.tipo='time' AND t.id=f.item_id LEFT JOIN jogadores j ON f.tipo='jogador' AND j.id=f.item_id LEFT JOIN confrontos c ON f.tipo='confronto' AND c.id=f.item_id LEFT JOIN times a ON a.id=c.time_casa LEFT JOIN times b ON b.id=c.time_visitante WHERE f.usuario_id=? ORDER BY f.criado_em DESC");$q->execute([$usuarioId]);$favoritos=$q->fetchAll();
$titulo_pagina='SUBZERO · Favoritos'; require __DIR__.'/includes/header.php';
?>
<section class="page-hero page-hero-sm"><div class="page-hero-overlay"></div><div class="container page-hero-content"><p class="eyebrow">Sua seleção pessoal</p><h1 class="page-title">MEUS <span class="outline">FAVORITOS</span></h1><p class="page-lead">Guarde equipes, jogadores e confrontos para encontrá-los rapidamente. Seus favoritos são vinculados à sua conta.</p></div></section>
<section class="container section favorites-layout">
<?php if($flash):?><div class="alert alert-<?=$tipoFlash==='error'?'error':'success'?>"><?=e($flash)?></div><?php endif;?>
<div class="card favorite-add"><h2 class="card-title">Adicionar favorito</h2><form method="post" class="form form-inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="acao" value="adicionar"><label class="field"><span>Categoria</span><select name="tipo" id="favoriteType" required><option value="time">Equipe</option><option value="jogador">Jogador</option><option value="confronto">Confronto</option></select></label><label class="field field-grow"><span>Escolha um item</span><select name="item_id" id="favoriteItem" required><?php foreach($times as $t):?><option data-tipo="time" value="<?=(int)$t['id']?>"><?=e($t['nome'])?></option><?php endforeach;?><?php foreach($players as $j):?><option data-tipo="jogador" value="<?=(int)$j['id']?>">#<?=(int)$j['numero']?> <?=e($j['nome'])?> · <?=e($j['time_nome'])?></option><?php endforeach;?><?php foreach($matches as $c):?><option data-tipo="confronto" value="<?=(int)$c['id']?>"><?=e($c['casa'].' × '.$c['fora'])?><?=!empty($c['data_hora'])?' · '.e(date('d/m/Y H:i',strtotime($c['data_hora']))):''?></option><?php endforeach;?></select></label><button class="btn btn-primary" type="submit">☆ Favoritar</button></form></div>
<div class="favorites-heading"><div><span class="section-kicker">COLEÇÃO PESSOAL</span><h2>Itens salvos</h2></div><span class="favorites-count"><?=count($favoritos)?> favorito(s)</span></div>
<?php if(!$favoritos):?><div class="empty-state">Você ainda não favoritou nada. Escolha uma equipe, jogador ou confronto acima.</div><?php else:?><div class="favorites-grid"><?php foreach($favoritos as $f):$label=$f['tipo']==='time'?($f['time_nome']??'Equipe removida'):($f['tipo']==='jogador'?(isset($f['jogador_nome'])?'#'.(int)$f['numero'].' '.$f['jogador_nome'].' · '.$f['time_nome']:'Jogador removido'):($f['casa']??'Equipe removida').' × '.($f['fora']??'Equipe removida'));?><article class="favorite-card"><span class="favorite-type"><?= $f['tipo']==='time'?'EQUIPE':($f['tipo']==='jogador'?'JOGADOR':'CONFRONTO')?></span><h3><?=e($label)?></h3><?php if($f['tipo']==='confronto'):?><p><?=!empty($f['data_hora'])?e(date('d/m/Y H:i',strtotime($f['data_hora']))):'Data a definir'?><?=!empty($f['quadra'])?' · '.e($f['quadra']):''?><?=!empty($f['cidade'])?' · '.e($f['cidade']).'/'.e($f['estado']??''):''?></p><?php endif;?><div class="favorite-actions"><?php if($f['tipo']==='time'&&!empty($f['time_nome'])):?><a class="btn btn--ghost btn-sm" href="time.php?id=<?=(int)$f['item_id']?>">Ver equipe</a><?php elseif($f['tipo']==='jogador'&&!empty($f['jogador_nome'])):?><a class="btn btn--ghost btn-sm" href="artilharia.php">Ver artilharia</a><?php elseif($f['tipo']==='confronto'&&!empty($f['casa'])):?><a class="btn btn--ghost btn-sm" href="confrontos.php">Ver confrontos</a><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="acao" value="remover"><input type="hidden" name="tipo" value="<?=e($f['tipo'])?>"><input type="hidden" name="item_id" value="<?=(int)$f['item_id']?>"><button class="btn btn-danger btn-sm" type="submit">Remover</button></form></div></article><?php endforeach;?></div><?php endif;?>
</section><script>
(()=>{const type=document.getElementById('favoriteType'),item=document.getElementById('favoriteItem');if(!type||!item)return;const filter=()=>{let first=null;for(const opt of item.options){const show=opt.dataset.tipo===type.value;opt.hidden=!show;opt.disabled=!show;if(show&&first===null)first=opt;}if(first)item.value=first.value;};type.addEventListener('change',filter);filter();})();
</script><?php require __DIR__.'/includes/footer.php';?>
